/* Generated by Trae Work */
/* 首页：track 切换器 + 课程/科目卡片网格（含大纲/真题收录状态） */
"use strict";
(function () {
  document.addEventListener("DOMContentLoaded", () => {
    /* AI 助手：DeepSeek 快速入口（官网禁止 iframe 嵌入，只能新标签页打开） */
    const aiHint = document.getElementById("ai-hint");
    const DEEPSEEK = "https://chat.deepseek.com/";
    document.querySelectorAll("[data-ai-open]").forEach(btn => {
      btn.addEventListener("click", () => {
        window.open(DEEPSEEK, "_blank", "noopener");
        if (aiHint) aiHint.textContent = "已在新标签页打开 DeepSeek（首次使用需登录）。";
      });
    });
    document.querySelectorAll("[data-ai-prompt]").forEach(btn => {
      btn.addEventListener("click", async () => {
        const text = btn.dataset.aiPrompt;
        let clipOk = true;
        try { await navigator.clipboard.writeText(text); } catch (err) { clipOk = false; /* file:// 下部分浏览器限制剪贴板 */ }
        window.open(DEEPSEEK, "_blank", "noopener");
        if (aiHint) aiHint.textContent = (clipOk ? "提问词已复制到剪贴板，" : "本页环境下无法自动复制提问词，请手动输入，") + "DeepSeek 已在新标签页打开" + (clipOk ? " —— 粘贴（Ctrl+V）后发送即可。" : "。");
      });
    });

    const switcher = document.getElementById("home-track-switch");
    const content = document.getElementById("home-track-content");
    const saved = Store.get("home_track", "zikao");

    function renderZikao() {
      const cs = SITE_DATA.zikao;
      const nSyllabus = cs.courses.filter(c => c.has_syllabus).length;
      const card = h("div", { class: "card" });
      card.innerHTML = `
        <h3>自考课程总览（18 项）</h3>
        <p class="muted">笔试 15 门 + 实践 2 门 + 毕业论文。课程设置来源：
          <a href="${cs.courses_source.source_url}" target="_blank" rel="noopener">${cs.courses_source.source_platform}</a>
          （verified_at ${cs.courses_source.verified_at}）</p>
        <p class="muted" style="margin-top:6px;">大纲已收录：<strong>${nSyllabus}</strong> 门（03496 / 08789 / 01347 / 01799 / 10740，官方 .doc 大纲，含考核知识点）
           · 真题：<strong>${cs.papers.length}</strong> 套（<a href="past-papers.html">历年真题合计</a>）
           · 课程笔记：<strong>${Object.keys(window.NOTES_DEEP || {}).filter(k => k !== "meta").length}</strong> 门（<a href="notes.html">课程笔记</a>）
           · 公开笔记：<strong>${cs.notes.length}</strong> 篇</p>`;
      const grid = h("div", { class: "grid grid-3", style: "margin-top:16px;" });
      cs.courses.forEach(c => {
        let statuses = c.has_syllabus
          ? `<span class="badge ok">官方大纲已收录</span>`
          : `<span class="badge miss">大纲暂缺</span>`;
        if (c.reference_chapters) statuses += `<span class="badge warnb">有参考章节结构</span>`;
        const pc = cs.papers.filter(p => p.course_code === c.code).length;
        statuses += `<span class="badge ${pc ? "ok" : "miss"}">真题 ${pc} 套</span>`;
        const d = h("div", { class: "course-card" });
        d.innerHTML = `
          <div class="cc-head"><span class="cc-code">${c.code}</span><span class="badge code">${c.kind}</span></div>
          <div class="cc-name">${c.name}</div>
          ${c.old_code ? `<div class="cc-old">旧代码对照：${c.old_code}（仅作参考来源）</div>` : ""}
          <div class="cc-status">${statuses}</div>
          <a href="zikao.html#course-${c.code}" style="font-size:13px;">查看章节骨架 →</a>`;
        grid.appendChild(d);
      });
      content.innerHTML = "";
      content.appendChild(card);
      content.appendChild(grid);
    }

    function renderKaoyan() {
      const ky = SITE_DATA.kaoyan;
      const card = h("div", { class: "card" });
      card.innerHTML = `
        <h3>28 考研科目总览</h3>
        <p class="muted">初试科目：思想政治理论（100 分）、英语（二）（100 分）、数学（二）（150 分）、408 计算机学科专业基础综合（150 分）。本站覆盖数二 / 英二 / 408。</p>
        <p class="muted" style="margin-top:6px;">408 真题：<strong>2009—2026 分年试卷与答案</strong>（<a href="past-papers.html">历年真题合计</a>，来源 GitHub neville-studio/408-exam-paper）
           · 408 大纲骨架：<strong>4 门</strong>（以当年教育部大纲为准）
           · 刷题题库：<strong>${SITE_DATA.quiz.length}</strong> 题（2023 年真题选择题，含来源答案）</p>`;
      const grid = h("div", { class: "grid grid-2", style: "margin-top:16px;" });
      /* 408 卡片：内分四门子科目 */
      const e408 = h("div", { class: "card" });
      e408.innerHTML = `<h3>408 计算机学科专业基础综合</h3>
        <p class="muted">满分 ${ky.exam408.full_score} 分 · ${ky.exam408.duration_min} 分钟 · ${ky.exam408.question_structure}</p>`;
      const sub = h("div", { class: "grid grid-4", style: "margin-top:12px;" });
      ky.exam408.subjects.forEach(s => {
        const d = h("div", { class: "course-card" });
        d.innerHTML = `<div class="cc-name">${s.name}</div><div class="cc-old">${s.score} 分</div>
          <div class="cc-status"><span class="badge ok">大纲骨架 ${s.chapters.length} 章</span></div>`;
        sub.appendChild(d);
      });
      e408.appendChild(sub);
      const m2 = h("div", { class: "course-card" });
      m2.innerHTML = `<div class="cc-name">数学（二）</div><div class="cc-old">${ky.math2.scope[0]}</div>
        <div class="cc-status"><span class="badge ok">考试范围说明</span><span class="badge miss">真题以回忆版为主</span></div>`;
      const e2 = h("div", { class: "course-card" });
      e2.innerHTML = `<div class="cc-name">英语（二）</div><div class="cc-old">完形 10 + 阅读 50 + 翻译 15 + 写作 15 = 100 分</div>
        <div class="cc-status"><span class="badge ok">题型结构说明</span><span class="badge miss">真题以回忆版为主</span></div>`;
      grid.appendChild(e408); grid.appendChild(m2); grid.appendChild(e2);
      content.innerHTML = "";
      content.appendChild(card);
      content.appendChild(grid);
    }

    const renderers = { zikao: renderZikao, kaoyan: renderKaoyan };
    function activate(track) {
      Store.set("home_track", track);
      switcher.querySelectorAll("button").forEach(b => b.classList.toggle("active", b.dataset.track === track));
      renderers[track]();
    }
    switcher.addEventListener("click", e => {
      const b = e.target.closest("button[data-track]");
      if (b) activate(b.dataset.track);
    });
    activate(saved);
  });
})();
